import type { Metadata } from "next";

import { siteConfig } from "@/config/site";

/** Branded share image generated by `app/opengraph-image.tsx`. */
export const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} — ${siteConfig.tagline}`,
};

export const absoluteUrl = (path = "/") => `${siteConfig.url}${path === "/" ? "" : path}`;

const BUSINESS_ID = `${siteConfig.url}/#business`;
const WEBSITE_ID = `${siteConfig.url}/#website`;

type PageMetadataOptions = {
  /** Page title; the root layout appends " | Skyland Construction". */
  title: string;
  description: string;
  /** Path of the page, e.g. "/services". */
  path: string;
  /** Use the title as-is, without the site-name suffix. */
  absoluteTitle?: boolean;
};

/** Consistent title, description, canonical URL and social cards for a page. */
export function pageMetadata({ title, description, path, absoluteTitle = false }: PageMetadataOptions): Metadata {
  const socialTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_CA",
      siteName: siteConfig.name,
      url: path,
      title: socialTitle,
      description,
      images: [shareImage],
    },
    twitter: { card: "summary_large_image", title: socialTitle, description, images: [shareImage.url] },
  };
}

/** The business as a local GeneralContractor, referenced by id from other structured data. */
export function businessJsonLd() {
  const { contact, social, logo } = siteConfig;
  return {
    "@context": "https://schema.org",
    "@type": "GeneralContractor",
    "@id": BUSINESS_ID,
    name: siteConfig.name,
    alternateName: siteConfig.alternateNames,
    description: siteConfig.description,
    url: siteConfig.url,
    logo: absoluteUrl(logo.src),
    image: [absoluteUrl("/images/about/skyland-office-2002-quebec-ave.jpeg"), absoluteUrl("/images/hero/skyland-crew-installing-wall-panels.jpeg")],
    telephone: contact.phone,
    email: contact.email,
    address: { "@type": "PostalAddress", ...contact.postal },
    hasMap: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${siteConfig.name}, ${contact.address}`)}`,
    areaServed: contact.areaServed.map((name) => ({ "@type": name === "Saskatoon" ? "City" : "State", name })),
    sameAs: social.map((profile) => profile.href),
    knowsAbout: siteConfig.services.map((service) => service.label),
  };
}

export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": WEBSITE_ID,
    name: siteConfig.name,
    alternateName: siteConfig.alternateNames,
    url: siteConfig.url,
    inLanguage: "en-CA",
    publisher: { "@id": BUSINESS_ID },
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export const businessRef = { "@id": BUSINESS_ID };
